## modules/rds-postgres

```hcl
# modules/rds-postgres/main.tf
resource "aws_db_subnet_group" "this" {
  name       = "${var.name}-db-subnets"
  subnet_ids = var.subnet_ids
  tags       = var.tags
}

resource "aws_security_group" "db" {
  name_prefix = "${var.name}-db-"
  vpc_id      = var.vpc_id
  tags        = merge(var.tags, { Name = "${var.name}-db" })
}

resource "aws_security_group_rule" "db_ingress" {
  type                     = "ingress"
  from_port                = 5432
  to_port                  = 5432
  protocol                 = "tcp"
  security_group_id        = aws_security_group.db.id
  source_security_group_id = var.ingress_security_group_id
}

resource "aws_db_instance" "this" {
  identifier     = var.name
  engine         = "postgres"
  engine_version = var.engine_version
  instance_class = var.instance_class

  allocated_storage     = var.allocated_storage
  max_allocated_storage = var.max_allocated_storage
  storage_encrypted     = var.storage_encrypted

  db_name  = var.db_name
  username = var.db_username
  password = var.db_password # supplied via SOPS-decrypted var-file

  db_subnet_group_name   = aws_db_subnet_group.this.name
  vpc_security_group_ids = [aws_security_group.db.id]
  multi_az               = var.multi_az
  publicly_accessible    = false

  backup_retention_period = max(var.backup_retention_days, 7)
  deletion_protection     = true
  skip_final_snapshot     = false
  final_snapshot_identifier = "${var.name}-final-${formatdate("YYYYMMDDHHmmss", timestamp())}"

  tags = var.tags
}
```

```hcl
# modules/rds-postgres/variables.tf
variable "name"           { type = string }
variable "engine_version" { type = string, default = "16.3" }
variable "instance_class" { type = string }
variable "allocated_storage"   { type = number, default = 20 }
variable "max_allocated_storage" { type = number, default = 100 }
variable "storage_encrypted" { type = bool, default = true }
variable "multi_az"        { type = bool, default = false }
variable "backup_retention_days" { type = number, default = 7 }
variable "db_name"         { type = string }
variable "db_username"     { type = string }
variable "db_password" {
  type      = string
  sensitive = true
}
variable "subnet_ids"             { type = list(string) }
variable "vpc_id"                 { type = string }
variable "ingress_security_group_id" { type = string }
variable "tags" { type = map(string), default = {} }
```

```hcl
# modules/rds-postgres/outputs.tf
output "db_endpoint" {
  value = aws_db_instance.this.endpoint
}

output "db_arn" {
  value = aws_db_instance.this.arn
}

output "security_group_id" {
  value = aws_security_group.db.id
}
```

