## modules/iam-service-role

```hcl
# modules/iam-service-role/main.tf
data "aws_iam_policy_document" "trust" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = [var.oidc_provider_arn]
    }

    condition {
      test     = "StringEquals"
      variable = "${var.oidc_provider_host}:sub"
      values   = ["system:serviceaccount:${var.k8s_namespace}:${var.service_account_name}"]
    }
  }
}

resource "aws_iam_role" "this" {
  name               = var.role_name
  assume_role_policy = data.aws_iam_policy_document.trust.json
  tags               = var.tags
}

# Least-privilege access to the assets bucket (no wildcards)
data "aws_iam_policy_document" "bucket_access" {
  statement {
    sid    = "ListBucket"
    effect = "Allow"
    actions = ["s3:ListBucket"]
    resources = [var.bucket_arn]
  }

  statement {
    sid    = "ObjectActions"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:DeleteObject",
    ]
    resources = ["${var.bucket_arn}/*"]
  }
}

resource "aws_iam_role_policy" "bucket_access" {
  name   = "${var.role_name}-bucket-access"
  role   = aws_iam_role.this.id
  policy = data.aws_iam_policy_document.bucket_access.json
}
```

```hcl
# modules/iam-service-role/variables.tf
variable "role_name"           { type = string }
variable "oidc_provider_arn"   { type = string }
variable "oidc_provider_host"  { type = string }
variable "k8s_namespace"       { type = string }
variable "service_account_name" { type = string }
variable "bucket_arn"          { type = string }
variable "tags" { type = map(string), default = {} }
```

```hcl
# modules/iam-service-role/outputs.tf
output "role_arn" {
  value = aws_iam_role.this.arn
}
```

