## Root configuration (shared, per env dir)

```hcl
# envs/prod/main.tf  (dev/main.tf identical; differences live in tfvars)
terraform {
  backend "s3" {
    key = "app/prod/terraform.tfstate" # per-env key
  }
  required_providers {
    aws = { source = "hashicorp/aws", version = "~> 5.0" }
  }
}

provider "aws" {
  region = var.aws_region
}

module "assets_bucket" {
  source = "../../modules/s3-bucket"

  bucket_name           = "${var.environment}-app-assets"
  use_kms               = var.use_kms
  replication_enabled   = var.enable_replication
  replication_role_arn  = var.replication_role_arn
  replication_destination_bucket_arn = var.replication_dest_arn
  tags                  = local.tags
}

module "db" {
  source = "../../modules/rds-postgres"

  name            = "${var.environment}-app-db"
  instance_class  = var.db_instance_class
  multi_az        = var.db_multi_az
  db_name         = "appdb"
  db_username     = "appuser"
  db_password     = var.db_password # SOPS-decrypted at plan time
  subnet_ids      = var.private_subnet_ids
  vpc_id          = var.vpc_id
  ingress_security_group_id = var.eks_node_sg_id
  tags            = local.tags
}

module "service_role" {
  source = "../../modules/iam-service-role"

  role_name            = "${var.environment}-app-sa-role"
  oidc_provider_arn    = var.eks_oidc_provider_arn
  oidc_provider_host   = var.eks_oidc_provider_host
  k8s_namespace        = "app"
  service_account_name = "app-sa"
  bucket_arn           = module.assets_bucket.bucket_arn
  tags                 = local.tags
}

locals {
  tags = { Environment = var.environment, ManagedBy = "terraform" }
}
```

```hcl
# envs/prod/terraform.tfvars
environment         = "prod"
aws_region          = "us-east-1"
db_instance_class   = "db.t3.medium"
db_multi_az         = true
use_kms             = true
enable_replication  = true
replication_role_arn = "arn:aws:iam::123456789012:role/s3-replication"
replication_dest_arn = "arn:aws:s3:::prod-app-assets-replica"
vpc_id              = "vpc-xxxx"
private_subnet_ids  = ["subnet-a", "subnet-b"]
eks_node_sg_id      = "sg-xxxx"
eks_oidc_provider_arn  = "arn:aws:iam::123456789012:oidc-provider/oidc.eks.us-east-1.amazonaws.com/id/XXXX"
eks_oidc_provider_host = "oidc.eks.us-east-1.amazonaws.com/id/XXXX"
```

```hcl
# envs/dev/terraform.tfvars
environment       = "dev"
aws_region        = "us-east-1"
db_instance_class = "db.t3.micro"
db_multi_az       = false
use_kms           = false
enable_replication = false
vpc_id              = "vpc-yyyy"
private_subnet_ids  = ["subnet-c"]
eks_node_sg_id      = "sg-yyyy"
eks_oidc_provider_arn  = "arn:aws:iam::123456789012:oidc-provider/oidc.eks.us-east-1.amazonaws.com/id/YYYY"
eks_oidc_provider_host = "oidc.eks.us-east-1.amazonaws.com/id/YYYY"
```

